import { Component, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { Urls } from '../../../../core/common/Urls';
import { G } from '../../../../core/common/G';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { IonContent, AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GAccount } from '../../../../core/common/GAccount';
import { CourseService } from '../../../../data/service/course/course.service';
import { SliderService } from '../../../../data/service/site/Slider.service';

/** Backend: register tool in Super Admin Tuner Plus with this id. */
const TUNER_PLUS_TOOL_ID = 4;

@Component({
  selector: 'app-fuel-pump-lph',
  templateUrl: './fuel-pump-lph.component.html',
  styleUrls: ['./fuel-pump-lph.component.scss']
})
export class FuelPumpLphComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = 'sqe0a45';

  bsfcPreset = '0.5';

  form: FormGroup;

  lbPerHr = 0;
  lphMin = 0;
  lphRecommended = 0;
  gphRecommended = 0;
  injectorLph = 0;
  injectorHeadroomOk = true;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(TUNER_PLUS_TOOL_ID).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusFuelPumpVideo;

    this.form = this.fb.group({
      peakHp: [300, [Validators.required, Validators.min(30), Validators.max(5000)]],
      bsfc: [0.5, [Validators.required, Validators.min(0.35), Validators.max(0.9)]],
      dutyCycle: [85, [Validators.required, Validators.min(50), Validators.max(95)]],
      safetyMargin: [10, [Validators.required, Validators.min(0), Validators.max(50)]],
      numInjectors: [4, [Validators.required, Validators.min(1), Validators.max(16)]],
      injectorFlow: [440, [Validators.required, Validators.min(1), Validators.max(3000)]]
    });
  }

  onBsfcPresetChange() {
    this.form.patchValue({ bsfc: +this.bsfcPreset });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const peakHp = +this.form.value.peakHp;
          const bsfc = +this.form.value.bsfc;
          const duty = +this.form.value.dutyCycle / 100;
          const margin = +this.form.value.safetyMargin / 100;
          const numInjectors = +this.form.value.numInjectors;
          const injectorFlow = +this.form.value.injectorFlow;

          this.lbPerHr = peakHp * bsfc;

          // Gasoline LPH at max injector duty (common tuner formula, BSFC in lb/hp·hr)
          this.lphMin = this.lbPerHr / (1.585 * duty);
          this.lphRecommended = this.lphMin * (1 + margin);
          this.gphRecommended = this.lphRecommended / 3.785;

          this.injectorLph = (injectorFlow * numInjectors * 60 * duty) / 1000;
          this.injectorHeadroomOk = this.injectorLph >= this.lphMin;

          this.lbPerHr = Math.round(this.lbPerHr * 10) / 10;
          this.lphMin = Math.round(this.lphMin * 10) / 10;
          this.lphRecommended = Math.round(this.lphRecommended * 10) / 10;
          this.gphRecommended = Math.round(this.gphRecommended * 100) / 100;
          this.injectorLph = Math.round(this.injectorLph * 10) / 10;

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset() {

    this.bsfcPreset = '0.5';
    this.lbPerHr = 0;
    this.lphMin = 0;
    this.lphRecommended = 0;
    this.gphRecommended = 0;
    this.injectorLph = 0;
    this.injectorHeadroomOk = true;

    this.form.setValue({
      peakHp: 300,
      bsfc: 0.5,
      dutyCycle: 85,
      safetyMargin: 10,
      numInjectors: 4,
      injectorFlow: 440
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'peakHp':
        this.presentActiveAlertConfirm('حداکثر توان موتور (Hp) در نقطهٔ هدف — معمولاً توان flywheel/crank.');
        break;
      case 'bsfc':
        this.presentActiveAlertConfirm('BSFC برحسب lb/hp·hr؛ بنزین NA حدود ۰.۵، توربو ۰.۵۵–۰.۶۵، اتانول بالاتر.');
        break;
      case 'dutyCycle':
        this.presentActiveAlertConfirm('حداکثر duty cycle انژکتور (مثلاً ۸۵٪) — پمپ باید در این duty سوخت کافی بدهد.');
        break;
      case 'safetyMargin':
        this.presentActiveAlertConfirm('حاشیهٔ اطمینان روی ظرفیت پمپ (مثلاً ۱۰٪) برای افت ولتاژ یا خط.');
        break;
      case 'numInjectors':
        this.presentActiveAlertConfirm('تعداد انژکتور فعال برای بررسی ظرفیت سیستم تزریق.');
        break;
      case 'injectorFlow':
        this.presentActiveAlertConfirm('دبی هر انژکتور برحسب cc/min در فشار کاری (مثلاً ۳ bar).');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
